import sys
import os

sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'fuzz'))

import msgpacker


def enc(x):
    e = msgpacker.encoder()
    e.encode(x)
    return e.get_buf()


def dec(data):
    return msgpacker.decoder(data).decode()


def test_dict_header_boundaries():
    assert enc({}) == b'\x80'
    assert enc({i: i for i in range(15)})[0] == 0x8f
    assert enc({i: i for i in range(16)})[0] == 0xde
    assert enc({i: i for i in range(65536)})[0] == 0xdf


def test_dict_wire_bytes():
    assert enc({'a': 1}) == b'\x81\xa1a\x01'


def test_dict_round_trip():
    d = {'Hello': 'world', 'count': 123, 'flag': True, 'n': None,
         'blob': b'\x00\x01', 'list': [1, 2, 3]}
    r = dec(enc(d))
    assert r == {'Hello': 'world', 'count': 123, 'flag': True, 'n': None,
                 'blob': b'\x00\x01', 'list': (1, 2, 3)}
    assert isinstance(r, dict)


def test_nested_dicts():
    d = {'a': {'b': {'c': {'d': 1}}}, 'e': [{'f': 2}]}
    assert dec(enc(d)) == {'a': {'b': {'c': {'d': 1}}}, 'e': ({'f': 2},)}


def test_large_dict():
    d = {'key%d' % i: i for i in range(1000)}
    assert dec(enc(d)) == d


def test_int_keys():
    d = {1: 'one', 2: 'two', -5: 'neg'}
    assert dec(enc(d)) == d
